import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import TextEditor from 'flarum/common/components/TextEditor';
import TextEditorButton from 'flarum/common/components/TextEditorButton';
import extractText from 'flarum/common/utils/extractText';
import LineupModal from './components/LineupModal';
export default function addComposerLineupButton() {
  extend(TextEditor.prototype, 'toolbarItems', function (items) {
    if (!app.forum.attribute('canCreateLineup')) {
      return;
    }
    items.add('wss-lineup', m(TextEditorButton, {
      icon: "fas fa-users",
      onclick: () => {
        const editor = this.attrs.composer.editor;
        app.modal.show(LineupModal, {
          onImageCreated: imageUrl => {
            const imageAlt = extractText(app.translator.trans('m4v3rick4git-lineup.forum.composer.image_alt'));
            editor.insertAtCursor("\n\n![".concat(imageAlt, "](").concat(imageUrl, ")\n\n"), false);
          }
        });
      }
    }, app.translator.trans('m4v3rick4git-lineup.forum.composer.button_tooltip')), 20);
  });
}